 for(float maximum:{0.f,-1.f,0.5f,65536.f,std::numeric_limits<float>::quiet_NaN(),std::numeric_limits<float>::infinity()}){auto invalid=Actor();invalid.maximumStun=maximum;invalid.stun=0;Check(!Seed(Good(),invalid,Lease{},true).valid,"invalid configured maximum refuses");Check(RetireEmpty(invalid,1000).phase==Phase::empty,"invalid unseeded retirement refuses");}
 {auto invalid=Actor();invalid.maximumStun=3300;invalid.stun=3301;Check(!Seed(Good(),invalid,Lease{},true).valid,"current stun above configured maximum refuses");}
