  auto held=Commit(base,1000,true,true);auto rest=Native(base,5);Observe(held,Good(1100),rest);RequestWake(held,17,1100);rest.maximumStun=changedMaximum;Check(!Wake(Good(1200),rest,held).valid,"maximum drift cannot authorize wake CAS");auto driftReceipt=Observe(held,Good(1200),rest);Check(driftReceipt.holdControls&&driftReceipt.suppressProne&&driftReceipt.labAbortRequired&&!driftReceipt.retired,"active maximum drift retains lease and locks");
